-- 2026-11-21 每日收录：Xibalba、Biolab Disaster、Orb.Farm、it's a(door)able、Radius Raid，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('xibalba', 'Xibalba', 'Xibalba', 'xibalba xibal ba maya dixue sheji fps phoboslab dominic szablewski justin spice', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2014, 'action', '["射击","动作","3D"]', 230, 0.1, 'io', 'https://phoboslab.org/xibalba/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '走进玛雅地下世界，把金字塔一层层打穿', '一款 WebGL 第一人称射击：WASD 移动，鼠标瞄准开火，在丛林与金字塔里清理来袭的敌人。', 'A WebGL first-person shooter: move with WASD, aim and fire with the mouse, and fight through jungle and pyramid halls.', '由 Dominic Szablewski（Phoboslab）制作，角色设计由 Justin Spice 完成，音乐由 Andreas Lösch 创作，2014 年起在 phoboslab.org/xibalba 公开发布。原页托管在 phoboslab.org/xibalba，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab), with character design by Justin Spice and music by Andreas Lösch, and published on phoboslab.org/xibalba since 2014. Hosted at phoboslab.org/xibalba; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/xibalba.jpg', 1280, 800, 'center', '["assets/posters/xibalba.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -43, 1795226400000, 'Enter the Maya underworld and fight your way through the pyramid.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('biolab-disaster', 'Biolab Disaster', 'Biolab Disaster', 'biolab disaster shengwu shiyanshi zainan tiaoyue sheji pingtai phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2010, 'action', '["动作","平台","射击"]', 30, 0.1, 'io', 'https://playbiolab.com/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '冲进出事的生物实验室，边跳边打', '一款横向跳跃射击：方向键移动，X 跳跃，C 开火，在被污染的实验室里往前推进。', 'A side-scrolling jump-and-gun: move with the arrow keys, jump with X, shoot with C, and push through a contaminated lab.', '由 Dominic Szablewski（Phoboslab）制作，音乐由 Andreas Lösch 创作，2010 年起在 playbiolab.com 公开发布。原页托管在 playbiolab.com，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) with music by Andreas Lösch, and published at playbiolab.com since 2010. Hosted at playbiolab.com; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/biolab-disaster.jpg', 1280, 800, 'center', '["assets/posters/biolab-disaster.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -42, 1795226400000, 'Jump and shoot your way through a lab gone wrong.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('orb-farm', 'Orb.Farm', 'Orb.Farm', 'orb farm orbfarm shengtai qiu shuitank guan shengwu max bittker', 'Max Bittker', '', '', NULL, '', 0, 2019, 'puzzle', '["沙盒","模拟","创意"]', 40, 0.1, 'io', 'https://orb.farm/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '在一个密封玻璃球里，养出一座水中生态', '一款沙盒模拟：往球里放入沙子、水、藻类和水蚤，观察它们如何彼此制衡，慢慢形成一座自己的小海洋。', 'A sandbox sim: add sand, water, algae and daphnia to a sealed glass orb, and watch them settle into a tiny ocean of your own.', '由 Max Bittker 制作，源码以 MIT 许可在 GitHub 发布。原页托管在 orb.farm，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Max Bittker; the source is MIT-licensed on GitHub. Hosted at orb.farm; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/orb-farm.jpg', 1280, 800, 'center', '["assets/posters/orb-farm.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -41, 1795226400000, 'Tend a sealed aquatic world inside a glass orb.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('its-a-doorable', 'it''s a(door)able', 'it''s a(door)able', 'its a doorable keai de men door key nicky case ncasenmare', 'Nicky Case', '', '', NULL, '', 0, 2014, 'puzzle', '["益智","短篇","解谜"]', 0, 0.04, 'io', 'https://ncase.me/door/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '一把钥匙、一扇门，大约一分钟的小故事', '一款大约一分钟的迷你解谜：方向键移动，想办法让钥匙找到它的门。也可以在通关后写下自己的一句话，把链接送给别人。', 'A one-minute mini puzzle: move with the arrow keys and help a key find its door. Afterward you can write a short message and send the link to someone else.', '由 Nicky Case 制作，代码与绘画以 CC0 捐入公共领域。原页托管在 ncase.me/door，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Nicky Case; the code and art are dedicated to the public domain under CC0. Hosted at ncase.me/door; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/its-a-doorable.jpg', 1280, 800, 'center', '["assets/posters/its-a-doorable.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -40, 1795226400000, 'A key, a door, and about a minute of a tiny story.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('radius-raid', 'Radius Raid', 'Radius Raid', 'radius raid radiusraid sheji feichuan kongjian js13k jack rugile', 'Jack Rugile', '', '', NULL, '', 0, 2013, 'action', '["射击","动作"]', 0, 0.08, 'io', 'https://jackrugile.com/radius-raid/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在密集的弹幕里，把四周的敌机一圈圈打掉', '一款太空射击：WASD 或方向键移动，鼠标瞄准开火，坚持打完一波又一波的敌人，并捡起强化道具。', 'A space shooter: move with WASD or the arrow keys, aim and fire with the mouse, survive wave after wave, and pick up powerups.', '由 Jack Rugile 制作，源码以 MIT 许可在 GitHub 发布，是 2013 年 js13kGames 冠军作品。原页托管在 jackrugile.com/radius-raid，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Jack Rugile; the source is MIT-licensed on GitHub. It won js13kGames 2013. Hosted at jackrugile.com/radius-raid; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/radius-raid.jpg', 1280, 800, 'center', '["assets/posters/radius-raid.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -39, 1795226400000, 'Blast the swarm around you before it closes in.', '', '', 1);
